mapper.insert:
    SELECT
        'PAPD'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(PRODUCT_NO), LENGTH('PAPD' ) + 1)), 0) + 1, 6, '0')
    FROM PAYMENT_PRODUCT

INSERT INTO PAYMENT_PRODUCT (
	PRODUCT_NO
	, PRODUCT_NAME
	, PRODUCT_TYPE
	, PRODUCT_DETAIL
	, PRODUCT_PRICE
	, PRODUCT_IMG
	, PRODUCT_PERIOD
) VALUES (
	#{productNo}
	, #{productName}
	, #{productType}
	, #{productDetail}
	, #{productPrice}
	, #{productImg}
	, #{productPeriod}
)

mapper.update:
UPDATE PAYMENT_PRODUCT
SET 
PRODUCT_NAME = #{productName}
	, PRODUCT_DETAIL = #{productDetail}
	, PRODUCT_PRICE = #{productPrice}
	, PRODUCT_IMG = #{productImg}
	, PRODUCT_PERIOD = #{productPeriod}
WHERE PRODUCT_NO = #{productNo}
